     );
+
+    // Check the attributes of the row elements.
+    const setSizes = {
+      "row-1": 3,
+      "row-2": 3,
+      "row-2-1": 2,
+      "row-2-2": 2,
+      "row-3": 3,
+      "row-3-1": 1,
+      "row-3-1-1": 2,
+      "row-3-1-2": 2,
