+        `ariaLevel at index ${i}`
+      );
+      Assert.equal(
+        rowElement.ariaSetSize,
+        setSizes[id],
+        `ariaSetSize at index ${i}`
+      );
+      Assert.equal(
+        rowElement.ariaPosInSet,
+        id.split("-").at(-1), // IDs end with the position in the set.
+        `ariaPosInSet at index ${i}`
+      );
